import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import type { MediaItem } from '../types/media-item';
import { usePreferencesStore } from './usePreferencesStore';

/** Resume is offered only when progress is past this many seconds… */
export const RESUME_MIN_SECONDS = 30;
/** …and before this fraction of the runtime (else it's effectively finished). */
export const RESUME_MAX_RATIO = 0.95;
/** Throttle window for persisting the resume map to localStorage. */
const RESUME_PERSIST_THROTTLE = 5000;
const RESUME_KEY = 'phlix.resume';
/** Companion key holding per-id last-touched epoch-ms timestamps used to bound the
 *  resume map (LRU). Stored SEPARATELY so `phlix.resume`'s payload shape stays a
 *  flat `Record<string, number>` (id → seconds) for backward compatibility. */
const RESUME_TOUCHED_KEY = 'phlix.resume.touched';
/** Hard cap on the number of distinct ids the persisted resume map may hold. Beyond
 *  this, the least-recently-touched entries are evicted before each persist so the
 *  map can never grow unbounded across a user's lifetime of watching. */
export const RESUME_MAX_ENTRIES = 200;
/** 100-nanosecond ticks per second — the server reports playback position in these
 *  (Jellyfin-style) ticks; the local resume map is in whole seconds. */
export const TICKS_PER_SECOND = 10_000_000;

/**
 * A transport command pushed onto the store's command bus by a host OUTSIDE the
 * Vue tree (Electron tray / media keys, TV remotes). The live media component
 * (Player.vue or MiniPlayer.vue) watches `lastCommand` and applies it to its REAL
 * `<video>` element — mirroring the `bindMediaSession` pattern: the store records
 * an intent, the element owner enacts it. `seq` is bumped on every dispatch so two
 * identical successive commands still re-trigger the watcher.
 */
export interface PlayerCommand {
  type: 'seekTo' | 'seekBy';
  /** seconds (seekTo = absolute) or delta seconds (seekBy = relative). */
  value: number;
  /** bump id so two identical successive commands still trigger the watcher. */
  seq: number;
}

export interface MediaSessionHandlers {
  onPlay?: () => void;
  onPause?: () => void;
  onSeek?: (to: number) => void;
  onNext?: () => void;
  onPrevious?: () => void;
}

function readResumeMap(): Record<string, number> {
  if (typeof localStorage === 'undefined') return {};
  try {
    const raw = localStorage.getItem(RESUME_KEY);
    const parsed = raw ? (JSON.parse(raw) as unknown) : null;
    // Mirror `readTouchedMap`: a corrupt blob like "null" parses fine but is
    // not a usable object — returning it would flip `resumeMap.value` to null
    // and every later write would throw. A JSON ARRAY parses to an object too
    // (typeof-safe but index-shaped): a stored "[7,8,9]" would have become the
    // map itself and numeric ids would read as bogus positions, so
    // `!Array.isArray` refuses arrays with the same severity as the scalar
    // forms. Known design gap (not fixed here): the map is keyed by media id
    // only, so resume positions bleed across profiles on a shared browser.
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? (parsed as Record<string, number>) : {};
  } catch {
    return {};
  }
}

/** Best-effort read of the companion last-touched map. Always returns a usable
 *  object — a missing/corrupt/partial map just means those ids have no recorded
 *  touch time (treated as oldest), so eviction still works without it. */
function readTouchedMap(): Record<string, number> {
  if (typeof localStorage === 'undefined') return {};
  try {
    const raw = localStorage.getItem(RESUME_TOUCHED_KEY);
    const parsed = raw ? (JSON.parse(raw) as unknown) : null;
    // Same law as `readResumeMap`: refuse null, scalars AND JSON arrays — an
    // array would become the touched map itself and corrupt eviction order.
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? (parsed as Record<string, number>) : {};
  } catch {
    return {};
  }
}

/** Deterministic 32-bit FNV-1a over UTF-16 code units; Math.imul keeps every
 *  step in the exact-integer 32-bit lane, `>>> 0` normalises to unsigned. */
function fnv1a32(input: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h = Math.imul(h ^ input.charCodeAt(i), 0x01000193) >>> 0;
  }
  return h;
}

/** Deterministic 32-bit djb2 (h*33 + c) — an independent second stream so the
 *  composed id carries ~64 bits of discrimination, not 32. */
function djb2(input: string): number {
  let h = 5381;
  for (let i = 0; i < input.length; i++) {
    h = (Math.imul(h, 33) + input.charCodeAt(i)) >>> 0;
  }
  return h;
}

/**
 * Synthetic media id for a LOCAL file (S-ui-player-18): a per-file-unique,
 * deterministic key derived from the URL path — query/hash stripped and
 * percent-decoded, so the same file keeps the same id across reloads even
 * when the host adds cache-buster noise. Replaces the old shared constant
 * 'local', under which every local file collided in resumeMap/lastTouched
 * and paused positions bled across different videos. Two pure integer hash
 * streams (FNV-1a + djb2, base-36) keep this dependency-free, stable across
 * engines, and free of any crypto/secure-context requirement.
 */
function localMediaId(url: string): string {
  const path = url.split(/[?#]/)[0];
  let key = path;
  try {
    key = decodeURIComponent(path);
  } catch {
    /* malformed percent-escape — hash the raw path (deterministic either way) */
  }
  return `local-${fnv1a32(key).toString(36)}-${djb2(key).toString(36)}`;
}

/**
 * Parse a requested volume onto the store's 0–1 scale — the single channel
 * every volume write flows through. Non-finite input is refused (null):
 * Math.min/max PROPAGATE NaN, so the clamp alone cannot stop poison, and a
 * bad `volume` reaches <video>.volume raw (Player.vue mirrors it verbatim,
 * where real browsers throw IndexSizeError on a non-finite assignment) and
 * gets persisted back to prefs by VolumeControl's watch. Refusing keeps the
 * last good value; this is the volume twin of audit #14's resume-blob law
 * and of setCurrent's duration guard.
 */
function normalizeVolume(v: unknown): number | null {
  if (typeof v !== 'number' || !Number.isFinite(v)) return null;
  return Math.min(1, Math.max(0, v));
}

/**
 * Parse a requested rate onto the store's 0.25–4 window — the volume channel's
 * direct twin: Math.min/max PROPAGATE NaN, so non-finite input is refused
 * (null) rather than clamped, and a bad `rate` would otherwise land raw on
 * <video>.playbackRate where browsers throw (player-047). Every in-app writer
 * (SpeedMenu 0.25–2, the speedStep ladder, element-mirrored ratechange) already
 * lives inside the window, so the clamp only bounds out-of-band writes; a
 * refusal keeps the last good rate.
 */
function normalizeRate(r: unknown): number | null {
  if (typeof r !== 'number' || !Number.isFinite(r)) return null;
  return Math.min(4, Math.max(0.25, r));
}

/**
 * Media-delay bounds for the caption/audio offset channels (S-ui-once-16):
 * the stepper moves in 0.1 s steps and the window is ±10 s — a delay beyond
 * ten seconds means the user wants a track switch, not a delay.
 */
export const MEDIA_OFFSET_LIMIT_SECONDS = 10;
export const MEDIA_OFFSET_STEP_SECONDS = 0.1;

/**
 * Parse a requested offset onto the ±10 s window — the direct twin of
 * normalizeVolume/normalizeRate: non-finite input is REFUSED (null) rather
 * than clamped (Math.min/max propagate NaN), and the 0.1 s quantize absorbs
 * float step-drift (0.1×3 → 0.30000000000000004 lands back on exactly 0.3).
 * The 10 multiplier is 1 / MEDIA_OFFSET_STEP_SECONDS.
 */
function normalizeMediaOffset(v: unknown): number | null {
  if (typeof v !== 'number' || !Number.isFinite(v)) return null;
  const clamped = Math.min(MEDIA_OFFSET_LIMIT_SECONDS, Math.max(-MEDIA_OFFSET_LIMIT_SECONDS, v));
  return Math.round(clamped * 10) / 10;
}

/**
 * usePlayerStore (R1.3) — singleton playback state shared across routes so a
 * mini-player can keep playing during navigation and "resume" / "up-next" work.
 *
 * Holds the current media + queue, transport state (position/duration/buffered),
 * and user selections (volume/muted/rate/quality/subtitle) seeded from prefs. A
 * persisted, throttled resume map records per-media positions in the 30s–95% band.
 * Media Session metadata + handlers are wired via bindMediaSession().
 */
export const usePlayerStore = defineStore('phlix-player', () => {
  const prefs = usePreferencesStore();

  const current = ref<MediaItem | null>(null);
  /** Stream URL of the current media — so a mini-player can continue the EXACT
   *  stream across routes without re-deriving a URL. Set via setCurrent. */
  const streamUrl = ref('');
  const queue = ref<MediaItem[]>([]);
  const playing = ref(false);
  const position = ref(0);
  const duration = ref(0);
  const buffered = ref(0);

  const volume = ref(prefs.defaultVolume);
  const muted = ref(false);
  /** WHY `muted` is on, kept apart so the two mutes cannot be confused:
   *  true = the AUTOPLAY fallback silenced this source (browser policy — obey
   *  it for this attempt), false = any mute here is the USER's choice.
   *  `setCurrent` releases a forced mute when new media loads — a rejected
   *  `play()` belongs to ONE source's autoplay attempt and must never leak
   *  into the rest of the session (the production no-audio bug) — while a
   *  user mute persists until the user changes it. Invariant: this flag is
   *  only ever true while `muted` is true (every unmute path clears it). */
  const autoplayMuted = ref(false);
  const rate = ref(1);
  const quality = ref(prefs.defaultQuality);
  const subtitleLang = ref<string | null>(prefs.defaultSubtitleLang);
  // Session mirrors of the persisted delay carriers (S-ui-once-16), normalised
  // on the way in — a corrupt verbatim-hydrated preference can never land raw
  // on the render path. The CaptionsMenu steppers write both channels.
  const subtitleOffset = ref<number>(normalizeMediaOffset(prefs.subtitleOffsetSeconds) ?? 0);
  const audioOffset = ref<number>(normalizeMediaOffset(prefs.audioOffsetSeconds) ?? 0);

  const hlsMasterUrl = ref('');
  const miniPlayer = ref(false);
  const resumeMap = ref<Record<string, number>>(readResumeMap());
  /** INTERNAL per-id last-touched timestamps (epoch ms) driving LRU eviction of the
   *  bounded resume map. Deliberately NOT in the public store return — no consumer
   *  reads it; it exists only to decide which resume entries to drop at the cap. */
  const lastTouched = ref<Record<string, number>>(readTouchedMap());

  /** Command bus (see PlayerCommand) — the latest external transport intent. The
   *  live media component watches this and applies it to its real <video>. */
  const lastCommand = ref<PlayerCommand | null>(null);
  let cmdSeq = 0;

  const progress = computed(() => (duration.value > 0 ? position.value / duration.value : 0));
  const upNext = computed<MediaItem | null>(() => queue.value[0] ?? null);

  // ---- resume map (throttled persistence) ---------------------------------
  /** Stamp an id as touched-now (called on every write to the resume map). */
  function touch(id: string): void {
    lastTouched.value[id] = Date.now();
  }

  /**
   * Evict the least-recently-touched resume entries until at most `cap` remain,
   * dropping each evicted id from BOTH the resume map and the touched map. Ids with
   * no recorded touch time sort as oldest. Also prunes any orphaned touched entries
   * (ids no longer present in the resume map) so the companion map can't drift
   * unbounded either. Returns true if anything was removed.
   */
  function evictToCapacity(cap: number): boolean {
    const ids = Object.keys(resumeMap.value);
    // Prune orphaned touched entries (touched ids not in the resume map).
    let removed = false;
    for (const id of Object.keys(lastTouched.value)) {
      if (!(id in resumeMap.value)) {
        delete lastTouched.value[id];
        removed = true;
      }
    }
    if (ids.length <= cap) return removed;
    // Oldest-first by last-touched (absent → 0 → evicted first).
    ids.sort((a, b) => (lastTouched.value[a] ?? 0) - (lastTouched.value[b] ?? 0));
    const evictCount = ids.length - cap;
    for (let i = 0; i < evictCount; i++) {
      const id = ids[i];
      delete resumeMap.value[id];
      delete lastTouched.value[id];
    }
    return true;
  }

  let persistTimer: ReturnType<typeof setTimeout> | undefined;
  let lastPersist = 0;
  function persistResume(force = false): void {
    if (typeof localStorage === 'undefined') return;
    const write = () => {
      lastPersist = Date.now();
      const commit = () => {
        localStorage.setItem(RESUME_KEY, JSON.stringify(resumeMap.value));
        localStorage.setItem(RESUME_TOUCHED_KEY, JSON.stringify(lastTouched.value));
      };
      try {
        commit();
      } catch {
        // Likely a quota error. Make ONE eviction pass (drop the oldest ~25%) and
        // retry the write once; if it still fails, swallow it (no UX regression —
        // an unpersisted resume position is recoverable, an exception is not).
        try {
          evictToCapacity(Math.floor(Object.keys(resumeMap.value).length * 0.75));
          commit();
        } catch {
          /* ignore quota */
        }
      }
    };
    const since = Date.now() - lastPersist;
    if (force || since >= RESUME_PERSIST_THROTTLE) {
      clearTimeout(persistTimer);
      persistTimer = undefined;
      write();
    } else if (persistTimer === undefined) {
      // S-ui-player-24 (player-031): ONE armed timer per interval. The pending
      // flush serialises the LIVE maps when it fires, so the old per-call
      // clearTimeout/re-arm was pure churn on the ~4Hz hot path.
      persistTimer = setTimeout(() => {
        persistTimer = undefined;
        write();
      }, RESUME_PERSIST_THROTTLE - since);
    }
  }

  function inResumeBand(pos: number, dur: number): boolean {
    return dur > 0 && pos > RESUME_MIN_SECONDS && pos < dur * RESUME_MAX_RATIO;
  }

  /** Record (or clear) the resume position for a media id, throttled. */
  function saveResume(id: string, pos: number, dur: number): void {
    if (inResumeBand(pos, dur)) {
      const isNew = !(id in resumeMap.value);
      resumeMap.value[id] = Math.floor(pos);
      touch(id);
      if (isNew) evictToCapacity(RESUME_MAX_ENTRIES);
    } else {
      delete resumeMap.value[id]; // too early or effectively finished
      delete lastTouched.value[id];
    }
    persistResume();
  }

  function resumePositionFor(id: string | null | undefined): number | null {
    if (!id) return null;
    return resumeMap.value[id] ?? null;
  }
  function clearResume(id: string): void {
    delete resumeMap.value[id];
    delete lastTouched.value[id];
    persistResume(true);
  }

  /**
   * Merge server-side resume positions (seconds, keyed by media id) into the local
   * map — the cross-device resume READ path. Positions recorded on OTHER devices
   * (Roku/mobile, via their playback sessions) reach the web player here from
   * `GET /api/v1/users/me/continue-watching`, so a title you paused on the TV
   * offers to resume on the web.
   *
   * Fill-gaps policy: a position already in the local map (set by THIS device's
   * recent watching) always wins; server positions only seed ids the local map
   * doesn't already track. The local map carries no per-id timestamps, so this
   * conservative choice never overwrites a fresh local position with a possibly
   * staler server one. Persists once if anything changed.
   */
  function mergeServerResume(positions: Record<string, number>): void {
    let changed = false;
    for (const [id, seconds] of Object.entries(positions)) {
      if (id && !(id in resumeMap.value) && seconds > 0) {
        resumeMap.value[id] = Math.floor(seconds);
        touch(id);
        changed = true;
      }
    }
    if (changed) {
      // Server-seeded ids count toward the cap too — bound the map before persisting
      // so a large continue-watching payload can't blow past RESUME_MAX_ENTRIES.
      evictToCapacity(RESUME_MAX_ENTRIES);
      persistResume(true);
    }
  }

  // ---- transport ----------------------------------------------------------
  function setCurrent(media: MediaItem, opts: { resetPosition?: boolean; streamUrl?: string } = {}): void {
    // New media = new autoplay attempt at the user's preferred loudness. An
    // autoplay-forced mute from the PREVIOUS source is released here (never a
    // user mute); if this source's play() is rejected again, Player.vue forces
    // the fallback once more — the browser's law per attempt, not per session.
    releaseAutoplayMute();
    // Single-src-owner law (phlix-ui-player-002/003): changing the media id
    // invalidates every previously advertised source. The old code only ever
    // OVERWROTE streamUrl when opts carried one and never touched
    // hlsMasterUrl — so an advance through a failed/absent resolver (next()
    // with no fresh URL) left the PREVIOUS item's streamUrl and master on the
    // store, and the MiniPlayer dock would attach the stale master to the new
    // item. Clear-first, opts-second: an explicit opts.streamUrl still wins
    // (next(resolver) threads the fresh URL), and a same-id in-place re-set
    // (Player.vue keeps the live session warm across props churn) preserves
    // both URLs exactly as before. useHlsTranscode.start intentionally does
    // NOT route through here for the master (it persists over the same-id
    // store state) — that same-id path is what keeps this law coherent.
    if (current.value && current.value.id !== media.id) {
      streamUrl.value = '';
      hlsMasterUrl.value = '';
    }
    current.value = media;
    if (opts.streamUrl !== undefined) streamUrl.value = opts.streamUrl;
    if (opts.resetPosition !== false) {
      position.value = 0;
      // Seed the scrubber length from the server's probed total length (seconds)
      // when known, so it starts at the true total instead of growing as a
      // transcode/HLS stream loads. With no server duration this is 0 (today's
      // reset) and updateProgress fills it from the <video> element.
      duration.value =
        typeof media.duration === 'number' && isFinite(media.duration) && media.duration > 0 ? media.duration : 0;
      buffered.value = 0;
    }
    setMediaSessionMetadata(media);
  }

  function updateProgress(pos: number, dur?: number, buf?: number): void {
    position.value = pos;
    if (dur !== undefined) {
      if (duration.value > 0) {
        // A server-probed total is already seeded — only ADOPT the element's
        // duration if it is finite and LARGER, so the scrubber never shrinks below
        // the known total while a transcode/HLS stream is still loading.
        if (isFinite(dur) && dur > duration.value) duration.value = dur;
      } else {
        // No seed — keep the original behavior (the element's duration drives it).
        duration.value = dur;
      }
    }
    if (buf !== undefined) buffered.value = buf;
    const media = current.value;
    if (!media) return;
    // S-ui-player-24 (player-031): quantized change detection mirroring
    // useResumeReporter's Math.floor(position) watch. A transport tick that
    // leaves the persisted resume state untouched — the same whole second is
    // already recorded for THIS id, or we are outside the band with nothing
    // recorded — may not mutate the two maps, stamp a touch, re-arm the
    // persist timer, or write localStorage. The map itself is the guard's
    // memory: clearResume, eviction, or a direct saveResume re-arm the next
    // tick automatically (no stale internal cache to invalidate).
    const seconds = Math.floor(pos);
    const recorded = media.id in resumeMap.value;
    const unchanged = inResumeBand(pos, duration.value)
      ? recorded && resumeMap.value[media.id] === seconds
      : !recorded;
    if (unchanged) return;
    saveResume(media.id, pos, duration.value);
  }

  // ---- command bus (external transport seam) ------------------------------
  /** Request an ABSOLUTE seek (seconds). Records an intent on `lastCommand`; the
   *  live media component applies it to its real <video>. Does NOT touch the
   *  element or store position directly — the element's seek then drives
   *  `updateProgress`, exactly as a user scrubber seek does. */
  function seekTo(seconds: number): void {
    lastCommand.value = { type: 'seekTo', value: seconds, seq: ++cmdSeq };
  }
  /** Request a RELATIVE seek (delta seconds). See `seekTo`. */
  function seekBy(delta: number): void {
    lastCommand.value = { type: 'seekBy', value: delta, seq: ++cmdSeq };
  }

  /**
   * Play an arbitrary local file (Windows host "Open File…"). Builds a minimal
   * synthetic MediaItem (per-file-unique id derived from the URL — see
   * `localMediaId`; title from `meta` or the URL basename) and routes it
   * through the EXISTING setCurrent so all the usual media-session + transport
   * seeding runs, then clears the queue (a local file has no up-next). `url`
   * becomes the stream URL with a fresh position.
   */
  function playLocalFile(url: string, meta: Partial<MediaItem> = {}): void {
    const basename = decodeURIComponent(url.split(/[?#]/)[0].split('/').pop() ?? '') || url;
    const item: MediaItem = {
      id: localMediaId(url),
      name: basename,
      type: 'movie',
      poster_url: null,
      genres: [],
      year: null,
      rating: null,
      runtime: null,
      overview: null,
      actors: [],
      director: null,
      created_at: null,
      updated_at: null,
      ...meta,
    };
    setCurrent(item, { streamUrl: url, resetPosition: true });
    queue.value = [];
  }

  function play(): void {
    playing.value = true;
    if (typeof navigator !== 'undefined' && navigator.mediaSession) navigator.mediaSession.playbackState = 'playing';
  }
  function pause(): void {
    playing.value = false;
    if (current.value) saveResume(current.value.id, position.value, duration.value);
    persistResume(true);
    if (typeof navigator !== 'undefined' && navigator.mediaSession) navigator.mediaSession.playbackState = 'paused';
  }
  /**
   * Enact the autoplay fallback's mute for the CURRENT source only (Player.vue
   * calls this when `play()` rejects with NotAllowedError, before retrying the
   * element muted). No-op when the store is already muted: a user mute silences
   * the same element, so nothing is being FORCED — and the per-media release
   * must never get the chance to erase the user's choice later.
   */
  function muteForAutoplay(): void {
    if (muted.value) return;
    muted.value = true;
    autoplayMuted.value = true;
  }
  /** Release the mute the autoplay fallback forced — called on every media
   *  load (setCurrent) so stickiness dies with its source. Acts only while
   *  `autoplayMuted` is set; a user-chosen mute is not ours to clear. */
  function releaseAutoplayMute(): void {
    if (!autoplayMuted.value) return;
    autoplayMuted.value = false;
    muted.value = false;
  }
  function setVolume(v: number): void {
    const vol = normalizeVolume(v);
    if (vol === null) return; // refuse NaN/±Infinity — keep the last good volume
    volume.value = vol;
    if (vol > 0) {
      muted.value = false;
      autoplayMuted.value = false; // raising the volume is a USER unmute — the
    }                              // forced state must not outlive `muted` (invariant)
  }
  function toggleMute(): void {
    muted.value = !muted.value;
    autoplayMuted.value = false; // whatever this action just did, it is the user's choice now
  }
  function setRate(r: number): void {
    const rt = normalizeRate(r);
    if (rt === null) return; // refuse NaN/±Infinity — keep the last good rate
    rate.value = rt;
  }
  function setQuality(q: string): void {
    quality.value = q;
  }
  function setSubtitle(lang: string | null): void {
    subtitleLang.value = lang;
  }
  /** Subtitle render delay (S-ui-once-16): positive = captions later. Refused
   *  non-finite input keeps the last good value (normalizeMediaOffset twin of
   *  setVolume/setRate); a successful write mirrors to the persisted carrier. */
  function setSubtitleOffset(seconds: number): void {
    const off = normalizeMediaOffset(seconds);
    if (off === null) return;
    subtitleOffset.value = off;
    prefs.subtitleOffsetSeconds = off;
  }
  /** Audio-track delay (S-ui-once-16). The overlay consumes it as a paired
   *  compensation delta (captions are custom-painted; a single muxed element
   *  cannot delay its own audio here); hosts with a real audio graph read the
   *  same channel. */
  function setAudioOffset(seconds: number): void {
    const off = normalizeMediaOffset(seconds);
    if (off === null) return;
    audioOffset.value = off;
    prefs.audioOffsetSeconds = off;
  }

  // ---- queue / up-next ----------------------------------------------------
  function setQueue(items: MediaItem[]): void {
    queue.value = [...items];
  }
  function enqueue(item: MediaItem): void {
    queue.value.push(item);
  }
  /**
   * Advance to the next queued item; returns it (or null when the queue is empty).
   * Threads a fresh stream URL via `resolveStreamUrl` so advancing never leaves a
   * STALE `streamUrl` (the previous item's): with no resolver — or one that returns
   * nothing — `streamUrl` is CLEARED to '' rather than left pointing at the prior
   * stream (the mini-player gates on `streamUrl`, so it hides instead of playing the
   * wrong media). R3.9's PlayerPage supplies the real `/media/:id/stream` resolver.
   */
  function next(resolveStreamUrl?: (m: MediaItem) => string | undefined): MediaItem | null {
    const n = queue.value.shift() ?? null;
    if (n) setCurrent(n, { streamUrl: resolveStreamUrl?.(n) ?? '' });
    return n;
  }

  // ---- mini-player --------------------------------------------------------
  function showMiniPlayer(): void {
    miniPlayer.value = true;
  }
  function hideMiniPlayer(): void {
    miniPlayer.value = false;
  }
  function closePlayer(): void {
    if (current.value) saveResume(current.value.id, position.value, duration.value);
    persistResume(true);
    playing.value = false;
    miniPlayer.value = false;
    current.value = null;
    streamUrl.value = '';
    hlsMasterUrl.value = '';
    // player-047: a closed session must not leave its title on the OS lock
    // screen — same availability guard as setMediaSessionMetadata, mirrored
    // down to the clear.
    if (typeof navigator !== 'undefined' && 'mediaSession' in navigator) {
      navigator.mediaSession.metadata = null;
    }
  }

  // ---- Media Session ------------------------------------------------------
  function setMediaSessionMetadata(media: MediaItem): void {
    if (typeof navigator === 'undefined' || !('mediaSession' in navigator)) return;
    const MM = (globalThis as { MediaMetadata?: typeof MediaMetadata }).MediaMetadata;
    if (!MM) return;
    navigator.mediaSession.metadata = new MM({
      title: media.name,
      artist: media.director ?? media.genres?.join(', ') ?? '',
      album: media.year ? String(media.year) : '',
      artwork: media.poster_url ? [{ src: media.poster_url }] : [],
    });
  }

  /** Push the current position/duration/rate to the OS Media Session so the
   *  lock-screen/notification scrubber reflects progress. Guarded + best-effort. */
  function setMediaPositionState(): void {
    if (typeof navigator === 'undefined' || !('mediaSession' in navigator)) return;
    const ms = navigator.mediaSession;
    if (typeof ms.setPositionState !== 'function') return;
    if (!(duration.value > 0) || !Number.isFinite(duration.value)) return;
    try {
      ms.setPositionState({
        duration: duration.value,
        position: Math.min(Math.max(0, position.value), duration.value),
        playbackRate: rate.value || 1,
      });
    } catch {
      /* invalid state (e.g. position > duration mid-seek) — ignore */
    }
  }

  /** Wire OS/lock-screen transport controls. Returns a teardown that clears them. */
  function bindMediaSession(handlers: MediaSessionHandlers): () => void {
    if (typeof navigator === 'undefined' || !('mediaSession' in navigator)) return () => {};
    const ms = navigator.mediaSession;
    const set = (action: MediaSessionAction, fn: (() => void) | ((d: MediaSessionActionDetails) => void) | null) => {
      try {
        ms.setActionHandler(action, fn as MediaSessionActionHandler | null);
      } catch {
        /* unsupported action — ignore */
      }
    };
    if (handlers.onPlay) set('play', handlers.onPlay);
    if (handlers.onPause) set('pause', handlers.onPause);
    if (handlers.onNext) set('nexttrack', handlers.onNext);
    if (handlers.onPrevious) set('previoustrack', handlers.onPrevious);
    if (handlers.onSeek) {
      set('seekto', (d: MediaSessionActionDetails) => handlers.onSeek?.(d.seekTime ?? 0));
    }
    return () => {
      for (const a of ['play', 'pause', 'nexttrack', 'previoustrack', 'seekto'] as MediaSessionAction[]) set(a, null);
    };
  }

  /** Re-seed volume/quality/subtitle/offsets from the current preferences (e.g. on open). */
  function seedFromPreferences(): void {
    // defaultVolume arrives from a verbatim-hydrated localStorage blob, so it
    // flows through the same parse channel instead of a raw assignment.
    const vol = normalizeVolume(prefs.defaultVolume);
    if (vol !== null) volume.value = vol;
    quality.value = prefs.defaultQuality;
    subtitleLang.value = prefs.defaultSubtitleLang;
    const subOff = normalizeMediaOffset(prefs.subtitleOffsetSeconds);
    if (subOff !== null) subtitleOffset.value = subOff;
    const audOff = normalizeMediaOffset(prefs.audioOffsetSeconds);
    if (audOff !== null) audioOffset.value = audOff;
  }

  return {
    current,
    streamUrl,
    queue,
    playing,
    position,
    duration,
    buffered,
    volume,
    muted,
    autoplayMuted,
    rate,
    quality,
    subtitleLang,
    subtitleOffset,
    audioOffset,
    hlsMasterUrl,
    miniPlayer,
    resumeMap,
    lastCommand,
    progress,
    upNext,
    inResumeBand,
    saveResume,
    resumePositionFor,
    clearResume,
    mergeServerResume,
    setCurrent,
    updateProgress,
    seekTo,
    seekBy,
    playLocalFile,
    play,
    pause,
    setVolume,
    toggleMute,
    muteForAutoplay,
    setRate,
    setQuality,
    setSubtitle,
    setSubtitleOffset,
    setAudioOffset,
    setQueue,
    enqueue,
    next,
    showMiniPlayer,
    hideMiniPlayer,
    closePlayer,
    setMediaSessionMetadata,
    setMediaPositionState,
    bindMediaSession,
    seedFromPreferences,
  };
});
